INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "徐达", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "濠州人，1353年随朱元璋南略。", "biography": null, "status": "draft", "id": "0f28446e-78b0-5db1-9677-98777005803e"}, {"name": "常遇春", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "怀远人，1355年投朱元璋、采石先登。", "biography": null, "status": "draft", "id": "51d50a75-07e1-574f-b22d-1fded66288ff"}, {"status": "draft", "name": "朱元璋", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "钟离人，少因饥疫丧家出家皇觉寺，1352年投郭子兴于濠州，后娶其养女。", "biography": null, "id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e"}, {"name": "朱文正", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "朱元璋伯兄之子，1354年来归。", "biography": null, "status": "draft", "id": "56dcc7d8-3f0f-52f6-8948-26a4293a5819"}, {"name": "胡深（元处州参谋）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "处州人，舒穆嚕宜逊所辟军事参谋，后来率民兵援婺州而败退；不并1161年宋水寨都统领。", "biography": null, "status": "draft", "id": "262dce27-dbc9-5fdc-9dc8-dc462e559fd3"}, {"name": "陈友定（元福建参政）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "福建参政，复汀州。", "biography": null, "status": "draft", "id": "116044d6-cea0-5450-96d8-a4d9b1db3059"}, {"name": "李文忠", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "朱元璋姊子，1354年归舅获赐朱姓。", "biography": null, "status": "draft", "id": "937816d2-8a96-5b84-9cae-f26cdcacfa7b"}, {"name": "朱亮祖", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "义兵元帅，先降朱又叛，1357年宁国被擒获释。", "biography": null, "status": "draft", "id": "5c1a83a7-a770-5dc7-9fbd-e713e03e8e72"}, {"name": "康茂才", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "水寨元帅，集庆陷后率众降朱。", "biography": null, "status": "draft", "id": "f04c265d-38f9-5b72-9c39-567870658cd2"}, {"name": "明玉珍", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "随州人，从徐寿辉，1357年领舟取重庆。", "biography": null, "status": "draft", "id": "4e68200c-5dfc-5811-96fa-2de59fb619e3"}, {"status": "draft", "name": "韩林儿", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "韩山童之子，父被擒后与杨氏逃武安。", "biography": null, "id": "15a71da9-cd6f-5a0b-ba68-144469ebde18"}, {"name": "傅友德", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "原陈友谅小孤山守将，1361年降吴。", "biography": null, "status": "draft", "id": "052c6ab9-234a-5d89-9bad-ec31f6774b50"}, {"status": "draft", "name": "方国珍", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "家世海贩盐，1348年因仇家指控通寇杀仇入海聚众，执元将并拒授定国尉，1350年再攻温州。", "biography": null, "id": "13233500-bcaf-50d6-822a-fd99bc0ec709"}, {"name": "张士诚", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "白驹场盐民，率众起兵，陷高邮称诚王建周。", "biography": null, "status": "draft", "id": "7fbe0af4-cc39-5fb7-9fa8-c94e110ad986"}, {"name": "李善长", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "1353年受朱元璋留为幕书记。", "biography": null, "status": "draft", "id": "fcb986aa-d440-5732-984a-f4c744f5a06d"}, {"name": "汤和", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年夺桥取和阳，后从朱渡江。", "biography": null, "status": "draft", "id": "76a3c1b3-e175-593d-99d7-63da30cef072"}, {"name": "胡廷瑞", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "陈友谅江西丞相，降吴，康泰舅。", "biography": null, "status": "draft", "id": "802e1135-35a4-5a18-8000-e933e784a608"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "胡海洋攻克宝庆，靖州等处官司归降", "description": "徐达派千户胡海洋攻克宝庆，守将唐龙逃走。靖州军民安抚司及各长官司随后都来归降，徐达一一赏赐，遣其回去。", "start_year": 1365, "end_year": 1365, "time_original": "《续资治通鉴》卷218；本事原载纪年折合公元1365年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8b355a71-3d3f-56dd-ae7d-14a6a1008330"}, {"title": "常遇春、邓愈攻克赣州，接受熊天瑞归降", "description": "常遇春、邓愈围攻赣州五个月后，熊天瑞因援绝粮尽，先派元震出降，随后自己袒身到军门请降，献出全部辖地。常遇春将熊天瑞送到建康。朱元璋听说攻克赣州而没有杀戮，十分欣喜，遣使褒奖常遇春。", "start_year": 1365, "end_year": 1365, "time_original": "《续资治通鉴》卷218；本事原载纪年折合公元1365年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "69b0dd61-08b9-542b-a5a9-8e48a1c3b8ed"}, {"title": "常遇春遣使招抚，韶州、南雄守将归降", "description": "常遇春进军南安，派危正越过山岭，招抚韶州等尚未攻下的郡。韶州守将张秉彝、南雄守将孙荣祖分别登记所部兵粮，前来归降。常遇春命王屿守南雄，张秉彝仍守韶州。", "start_year": 1365, "end_year": 1365, "time_original": "《续资治通鉴》卷218；本事原载纪年折合公元1365年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a3644633-f8ec-5a68-b588-26ddf08fe7b3"}, {"title": "朱文正被免官，安置桐城", "description": "朱文正对赏赐有所不满，任由卫可达掳掠辖区人口。李饮冰奏劾他骄奢怨望，又称其有异志。朱元璋亲到南昌，将朱文正带回建康。王妃竭力劝解，群臣则请依法处置。朱元璋顾念朱文正是哥哥唯一的儿子，不忍杀死，只免官安置桐城，并命王妃抚养他四岁的儿子守谦。", "start_year": 1365, "end_year": 1365, "time_original": "《续资治通鉴》卷218；本事原载纪年折合公元1365年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "24780eaa-4a07-561a-b718-cd87e725301f"}, {"title": "胡深救援处州，追击攻克浦城", "description": "陈友定进攻处州，胡深率兵救援。陈友定听说胡深到来便退去，胡深追到浦城，击败出城抵抗的守军，攻下浦城。", "start_year": 1365, "end_year": 1365, "time_original": "《续资治通鉴》卷218；本事原载纪年折合公元1365年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6ed4d3e8-d24d-5fbe-9fbb-e4780fa42331"}, {"title": "朱文忠在新城大败张士诚军", "description": "朱文忠命徐大兴、汤克明领左军，严德、王韶领右军，自己统中军迎敌；胡深又派耿天璧率援军到达。朱文忠率铁骑冲击敌军中坚，左右两军乘势进攻，城中守兵也出击，张士诚军大败，被追赶十余里，斩首数万级。朱亮祖、张斌继续追击，俘获韩谦等六百人、甲士三千人。李伯升、谢再兴仅仅脱身逃走。", "start_year": 1365, "end_year": 1365, "time_original": "《续资治通鉴》卷218；本事原载纪年折合公元1365年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "59bfc69b-e8a9-5601-b5b2-acd929387631"}, {"title": "朱元璋命常遇春进取襄阳等郡", "description": "朱元璋曾向徐达等说明，安陆、襄阳是连通荆蜀、南北相争的要地，沔阳又刚归附，应增兵防守，使各地互相声援。此时，他命常遇春率军进取襄阳等郡。", "start_year": 1365, "end_year": 1365, "time_original": "《续资治通鉴》卷218；本事原载纪年折合公元1365年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6d145221-c0c9-5560-8211-5331d957b256"}, {"title": "常遇春攻下安陆，吴复留守", "description": "常遇春进攻安陆，击败并俘获守将任亮，攻下城池，命沔阳卫指挥吴复留守。朱元璋此前已将邓愈调任湖广平章，命他随后进军，驻兵安抚归附者，并部署沔阳、景陵、武昌相互支援。", "start_year": 1365, "end_year": 1365, "time_original": "《续资治通鉴》卷218；本事原载纪年折合公元1365年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4896c858-61a1-580a-bf59-a03193df8fe0"}, {"title": "常遇春取襄阳、受谷城降，章溢建议屯田", "description": "襄阳守将弃城逃走，常遇春追击，俘获五千人。张德、罗明又献谷城归降，被送往建康。朱元璋任章溢为湖广按察佥事，章溢认为荆襄多有荒废土地，建议分兵屯田，朱元璋赞同。", "start_year": 1365, "end_year": 1365, "time_original": "《续资治通鉴》卷218；本事原载纪年折合公元1365年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b3714a50-43b5-549b-8ccf-25b504b6cab3"}, {"title": "胡深进攻建宁被俘，后遭杀害", "description": "朱亮祖等进攻建宁。胡深认为气象不利，主张暂缓，朱亮祖却不断督促。胡深进兵打破两座栅垒后，被阮德柔重围；突围时又遇伏兵，战马跌倒，遂被俘送往陈友定处。陈友定起初礼待胡深，并无杀意，后来元朝使者到来督逼，胡深终于遇害。", "start_year": 1365, "end_year": 1365, "time_original": "《续资治通鉴》卷218；本事原载纪年折合公元1365年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6872365c-9ce7-5263-8d6a-31f9bf4a59ab"}, {"title": "朱元璋下令抚恤渡江士卒及家属", "description": "七月，朱元璋下令供养当初随他渡江、因受伤而残疾的士卒，并供养阵亡士卒的妻子和儿女。", "start_year": 1365, "end_year": 1365, "time_original": "至正二十五年七月", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ab30b2be-264a-510a-ae3c-363741f5db37"}, {"title": "朱元璋一方设立国子学", "description": "九月丙辰，朱元璋一方设立国子学。", "start_year": 1365, "end_year": 1365, "time_original": "至正二十五年九月", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9e0e235f-bff2-5de7-acb8-2df1675f5b7f"}, {"title": "朱元璋下令讨张士诚，严禁掳掠军民", "description": "朱元璋指责张士诚屡次侵犯疆界，命大军出讨，只追究首恶；又告谕对方军民不必恐惧逃散，不要荒废农事，并命将领约束官兵、禁止掳掠，违者以军法处罚。", "start_year": 1365, "end_year": 1365, "time_original": "《续资治通鉴》卷218；本事原载纪年折合公元1365年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cd2e15ef-83aa-5c2e-b27c-583c31dd3b67"}, {"title": "徐达等奉命水陆并进，谋取淮东", "description": "朱元璋命徐达、常遇春、胡廷瑞、冯国胜、华高等率骑兵、步兵和舟师水陆并进，谋取泰州等地，打算先剪除张士诚在通、泰等处的羽翼，再集中进取浙西。", "start_year": 1365, "end_year": 1365, "time_original": "《续资治通鉴》卷218；本事原载纪年折合公元1365年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3ccf57ef-fd76-557f-84df-22f4bcd63c13"}, {"title": "徐达、常遇春攻克泰州，擒严再兴等", "description": "徐达、常遇春攻克泰州，俘获严再兴、夏思忠、张士俊等，向建康献捷，并请示守城安排。朱元璋命徐达酌情处置，乘胜进取尚未攻下的各城。", "start_year": 1365, "end_year": 1365, "time_original": "《续资治通鉴》卷218；本事原载纪年折合公元1365年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "491b4a9c-6b7b-5808-95dd-d244db4bc99a"}, {"title": "徐达救援宜兴，击败张士诚军", "description": "张士诚军进攻宜兴，朱元璋命徐达安排冯国胜围高邮、常遇春守海安，另派将领守泰州，自己率精兵救援宜兴。徐达渡江到宜兴城下，击败张士诚军，俘获三千余人。", "start_year": 1365, "end_year": 1365, "time_original": "《续资治通鉴》卷218；本事原载纪年折合公元1365年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "abc1ea58-0c4f-5fda-ad99-1d13e295981f"}, {"title": "徐达回攻高邮，徐义援军驻太仓不进", "description": "徐达从宜兴撤回，进攻高邮。张士诚派徐义由海道进入淮地救援，徐义怨恨张士诚将自己置于死地，随后驻军昆山太仓，三个月没有前进。", "start_year": 1365, "end_year": 1365, "time_original": "《续资治通鉴》卷218；本事原载纪年折合公元1365年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b6a7b895-0664-5b1a-90a6-f3b9c9cd741b"}, {"title": "康茂才在浮子门追击张士诚军，伏兵截击上岸者", "description": "张士诚军进逼江阴，劫掠西津后退走。朱元璋亲自救援到镇江，命康茂才追击，另派一军埋伏江阴山下。次日，康茂才遇五百艘海船乘潮来攻，奋战将其击败。敌军弃船上岸者又遭伏兵截击。", "start_year": 1366, "end_year": 1366, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1366年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e707d2d1-8571-5c82-8743-19773ac986ff"}, {"title": "明玉珍病逝，明升继位，彭氏共同听政", "description": "明玉珍病中嘱咐臣僚同心辅佐继承人，随后去世，称帝共五年。十岁的儿子升继位，改元开熙，母亲彭氏共同听政。", "start_year": 1366, "end_year": 1366, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1366年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e06d3a6f-787d-51bd-bc29-6acfb8c36dc8"}, {"title": "朱元璋一方严惩地方官滥举人才", "description": "朱元璋一方此前已定府县每年荐举人才的赏罚，此时又令，府县官若滥举，来朝时治罪；尚未到朝觐期的，也要在年底拘到京师治罪。", "start_year": 1366, "end_year": 1366, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1366年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "02b4ca06-5f52-5a56-9cc7-011ccd9f5e52"}, {"title": "徐达督军攻下高邮，余同佥等被处死", "description": "徐达从宜兴返回后，加紧督促攻城，终于攻下高邮，处死余同佥等。朱元璋命将俘获的将士分别派往沔阳、辰州戍守，按等给予衣粮。", "start_year": 1366, "end_year": 1366, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1366年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bf277903-47c9-5d74-b411-e1ae111acf09"}, {"title": "徐达攻破徐义水寨，接受淮安投降", "description": "徐达夜袭马骡港徐义的水寨，徐义从海上逃走，朱元璋的水军进抵淮安城下。梅思祖等献军马、府库出降。徐达让军队驻在城墙上，百姓安定，又命蔡先、华云龙守城。", "start_year": 1366, "end_year": 1366, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1366年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bef94b73-464a-5eba-90de-48de0c1e3732"}, {"title": "朱元璋赴濠州祭墓，命徐达攻安丰", "description": "朱元璋前往濠州祭扫陵墓，许存仁、王祎随行。他听说珠展进入安丰，命徐达截断敌军粮道，会合骑兵出击。徐达接令，统率三万余水陆军队进攻安丰。", "start_year": 1366, "end_year": 1366, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1366年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9bba68ce-c37d-5efa-a285-7df4729a932b"}, {"title": "朱元璋宴请濠州父老，劝乡民暂勿远行", "description": "濠州父老经济等拜见朱元璋，受到宴请，与他谈旧。朱元璋劝他们教子行善、勤俭生活，又因附近仍有敌兵，劝乡民暂不远出，防止遭到劫掠。", "start_year": 1366, "end_year": 1366, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1366年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4c3f315e-f322-5195-85bf-abbf097a3914"}, {"title": "朱元璋从濠州返回建康", "description": "朱元璋从濠州返回建康。", "start_year": 1366, "end_year": 1366, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1366年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1dcb32bd-fa26-5fa9-9afe-519e415d9bc7"}, {"title": "朱元璋扩建建康城，营建新宫", "description": "朱元璋因旧宫地势低窄，此前命刘基等在钟山南面选择新宫地点，向东增筑新城，周长五十余里。", "start_year": 1366, "end_year": 1366, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1366年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f3b2339a-40d0-5914-970d-a17515023a50"}, {"title": "徐达、常遇春奉命率二十万军征讨张士诚", "description": "朱元璋命徐达为大将军、常遇春为副将军，率二十万军队征讨张士诚。他告诫军队，不准劫掠、滥杀、掘坟、毁屋，特别要求不得毁坏张士诚母亲的坟墓。", "start_year": 1366, "end_year": 1366, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1366年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ae61bec0-c164-55bd-b278-0e1451349375"}, {"title": "朱元璋决定先攻湖州，再攻苏州", "description": "常遇春请求直攻苏州，朱元璋认为应先削弱张天麟、潘元明的援助，先攻湖州，并以战败责任告诫常遇春，确定方案。朱元璋又秘密命熊天瑞随军，只让他听到直攻苏州的假消息。朱元璋判断他会叛投张士诚，借此将假情报传给敌方。", "start_year": 1366, "end_year": 1366, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1366年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "99ff8e94-54b5-5624-abe0-059aca4a15e3"}, {"title": "朱元璋命朱文忠攻杭州，牵制张士诚", "description": "朱元璋命朱文忠进攻杭州，以牵制张士诚集中在苏州的兵力。", "start_year": 1366, "end_year": 1366, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1366年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "31741ca0-34c2-55f3-88c0-70c284fc61b0"}, {"title": "常遇春进攻乌镇，王晟、戴茂投降", "description": "常遇春进攻乌镇，徐义、潘元绍战败逃走。他追到升山，攻破王晟的陆寨，戴茂、王晟先后投降。", "start_year": 1366, "end_year": 1366, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1366年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5df4f648-aae0-5fb0-9d93-8be59a0e6550"}, {"title": "张天麟献湖州，李伯升随同投降", "description": "徐达派降将吕珍、王晟等去劝城中投降。李伯升拒绝，想拔刀自杀，被身边人拦住。后来张天麟等献城，李伯升最终也投降。", "start_year": 1366, "end_year": 1366, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1366年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "52aaa7c1-d783-5b10-a80a-5b2354c91d35"}, {"title": "潘元明献杭州，朱文忠严禁军队扰民", "description": "潘元明派方彝请降，献上图籍、印信，并交出蒋英、刘震。朱文忠挥退迎接的女乐，禁止士卒擅入民居，将借民锅的士卒处死以示军纪。受降后接收兵员三万、粮食二十万，又将努都长寿等俘虏送往建康。", "start_year": 1366, "end_year": 1366, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1366年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6ef198b7-7b11-527e-8d2b-1e2631ebf9e5"}, {"title": "廖永忠在瓜步沉杀小明王韩林儿", "description": "小明王韩林儿从滁州前往建康时，被廖永忠在瓜步沉入水中杀害。", "start_year": 1366, "end_year": 1366, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1366年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ba93f37b-8041-59a1-9b37-a230a522c5e8"}, {"title": "朱元璋议定次年称吴元年，营建庙社宫室", "description": "群臣请求议定新宫制度，朱元璋认为应先重宗庙、社稷，决定次年称吴元年，命人营建庙社和宫室。他亲祭山川，告知工事，又删去宫室图中雕琢华丽的部分。", "start_year": 1366, "end_year": 1366, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1366年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "35d7930a-7bf2-51f3-9901-204d43749494"}, {"title": "朱元璋减免太平、应天等地田租", "description": "至正二十七年正月，朱元璋因当地长期受战乱和供给军需之苦，下令免太平两年田租，免应天、镇江、宁国、广德各一年田租。", "start_year": 1367, "end_year": 1367, "time_original": "至正二十七年正月", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6ca38ea3-6440-51a4-a375-83eb60a3a836"}, {"title": "傅友德设伏擒获库库特穆尔部将李二", "description": "李二率徐州兵到陵子村，陆聚命傅友德抵御。傅友德先率二千人，乘敌兵出外劫掠时进攻，刺中韩乙；随后返回城中，开门在野外列阵，等敌军再来时击鼓奋起，大败并擒获李二，升任江淮参政。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b9dda44f-5678-51d5-a67c-36006744a361"}, {"title": "朱元璋一方设置文武科选拔人才", "description": "三月丁丑，朱元璋一方开始设置文科和武科选拔人才。", "start_year": 1367, "end_year": 1367, "time_original": "至正二十七年三月", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9d938b9c-d198-569f-9f62-d870c3108d0b"}, {"title": "朱元璋责方国珍十二过，方国珍没有答复", "description": "方国珍入贡后，又暗中联系库库特穆尔、陈友定，等待苏州战事结果，再决定归顺还是反叛。朱元璋写信列举其十二项过失，劝他审慎决定，方国珍没有答复。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b7021387-aba7-5251-be93-bfd9ba03342e"}, {"title": "朱元璋一方设置翰林院", "description": "五月己亥，朱元璋一方首次设置翰林院。", "start_year": 1367, "end_year": 1367, "time_original": "至正二十七年五月", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7ebfb47c-692a-5d30-bd94-97a487b79a17"}, {"title": "朱元璋因旱减膳，免徐州等地税粮三年", "description": "朱元璋因久旱减膳、素食，下令免徐州、宿州、濠州、泗州、襄阳、安陆等郡税粮三年。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5b95fb33-4e50-5456-ae4e-8cc337aa6aab"}, {"title": "朱元璋在降雨后仍下令免征当年田租", "description": "下大雨后，群臣请求恢复朱元璋原有的膳食。朱元璋认为，虽然下雨，庄稼此前已多受损，便下令免除百姓当年田租。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0881110a-3c6f-52ea-aab7-889c62d25a51"}, {"title": "朱元璋下令朝贺不用女乐", "description": "朱元璋下令，今后朝贺一律不用女乐。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷219；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "72871aab-1d6b-5d49-8ad3-51651fbc1e57"}, {"title": "朱元璋责方国珍不履归附之约，要求贡粮", "description": "方国珍此前答应，杭州被攻下后就入朝，却仍据守原地，联络福建。朱元璋要求他贡献二十三万石粮食，写信劝他履约。方国珍害怕，召亲属与将佐商议；张本仁认为苏州未下，朱元璋军不能远来，刘庸则倚仗海船，邱楠劝他守信归降。方国珍不能决断，只日夜转运珍宝、聚集船只，准备出海。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "86d9d79c-ace9-58d2-9987-903f37261da0"}, {"title": "朱元璋一方建成圜丘、方丘及社稷坛", "description": "朱元璋一方建成圜丘、方丘及社稷坛，仿汉制筑为两层。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cc9745ef-c78e-518e-b135-b2cb6d3c8002"}, {"title": "朱元璋一方建成四代祖先的太庙", "description": "朱元璋一方建成太庙，四代祖先各有庙所：高祖居中，曾祖在东第一庙，祖父在西第一庙，父亲在东第二庙。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0971f409-f438-5627-ac92-2011b7972e2a"}, {"title": "朱元璋命朱亮祖征讨方国珍，严禁杀民", "description": "朱元璋命朱亮祖征讨方国珍，告诫他三州百姓已很困苦，攻下城池时不得杀害百姓。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a4cffb89-fa8b-57a0-a17b-e2e6ab190992"}, {"title": "徐达、常遇春攻克苏州，俘获张士诚", "description": "徐达攻破葑门，常遇春攻破阊门新寨，唐杰、周仁、潘元绍、刘毅先后投降。张士诚巷战失败，妻子刘氏自焚。张士诚闭门自缢，被李伯升、赵世雄救活，随后抬到船中。李行素、徐义、余介及元宗室神保、赫罕等被俘，送往建康，熊天瑞被处死。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e6b58208-ba50-5f30-a0b7-705496164fe9"}, {"title": "朱亮祖攻取台州，国瑛逃走，赵琬绝食而死", "description": "国瑛听马克让劝说后守台州，遇到猛烈进攻，便带妻儿逃到黄岩。朱亮祖攻取台州及仙居。总管赵琬被国瑛挟往黄岩，后来潜到白龙奥，寄居民家，绝食而死。赵琬是琏的弟弟。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7308a2bc-6b78-55da-821d-753f8db6b394"}, {"title": "朱元璋派人访贤，将苏州富民迁到濠州", "description": "朱元璋派吴琳、魏观携币帛到各地寻访未被任用的贤才，又将苏州富民迁往濠州，充实当地人口。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "55865d2e-107a-5447-a20b-a0e18fd29b2f"}, {"title": "朱元璋一方改礼制尚左，调整国子学、太史院官制", "description": "朱元璋一方规定礼仪尊左，将右相国改为左相国、左相国改为右相国，其他官职照办。又任许存仁为国子祭酒、刘承直为司业，将太史监改为太史院，命刘基为院使。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ade4de0f-35e9-540a-a091-9b5e80dfb47c"}, {"title": "朱元璋设御史台，任汤和、邓愈等为台官", "description": "朱元璋一方设御史台，以汤和、邓愈分别为左、右御史大夫，刘基、章溢为御史中丞。朱元璋告诫他们，正己尽责，不要假公济私、伤害他人。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d1953cc6-f225-53eb-94ef-de8079d7cfa1"}, {"title": "汤和、吴祯奉命征讨方国珍", "description": "朱元璋命汤和为征南将军，吴祯为副将，到庆元征讨方国珍。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1ac43a5a-4922-5475-8312-b25c44aade88"}, {"title": "朱元璋命李善长等制定律令", "description": "朱元璋命李善长为律令总裁官，杨宪、刘基、陶安等为议律官，告诫他们立法须简明、适中，将刑名条目逐一呈上，共同讨论。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9772fd3a-a4d3-5014-82a1-bf3c981a8414"}, {"title": "朱元璋确定先取山东等地，再进军元都", "description": "常遇春主张直接攻元都，朱元璋担心深入坚城之下，粮饷不继、援军四集，决定先取山东、河南，夺守潼关，截断元都援助，再行进攻。众将同意。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ee0c3c59-6d5c-5658-ace3-9608d712de3f"}, {"title": "朱元璋分兵取福建、广西，何文辉恢复何姓", "description": "朱元璋命胡廷瑞、何文辉进取福建，戴德随征；命杨璟、周德兴、周彬进取广西。何文辉原是朱元璋养子，曾赐朱姓，此时恢复何姓。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6c44b79c-d429-5f6c-86fc-1a4f29da67f5"}, {"title": "朱亮祖攻取温州、瑞安", "description": "朱亮祖攻取温州，方明善先行逃走；瑞安守将谢伯通献城投降。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "38c57d34-66bd-506d-9417-f09d1eb30cb2"}, {"title": "汤和攻克庆元，追击方国珍至海上", "description": "汤和经过余姚、上虞，接受李密、沈温投降，到庆元后又接受徐善等投降。方国珍带部众出海，汤和追击，将其击败，擒获方惟益。方国珍带余众再次入海，汤和返回庆元，攻取定海、慈溪。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "69afdc77-cb44-5969-a5ac-fbaae615e9c4"}, {"title": "徐达攻破沂州，处死王宣，王信逃走", "description": "王宣扣留徐唐等使者，徐唐脱身报告，徐达便围攻沂州。王宣假意答应投降，又闭门抵抗，最后开门出降。王信杀死携父亲书信来招降的孙惟德，与兄长仁逃往山西。各县归降后，徐达处死王宣，命韩温守沂州。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9674815f-24ef-5c9d-8b32-aa6ce198e069"}, {"title": "方国珍派文信、郭春请降", "description": "朱元璋命廖永忠从海路会合汤和，征讨方国珍。方国珍派郭春及儿子文信到朱亮祖处表示归顺。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3e7b135e-a784-52a8-a8cd-a3c581381fbf"}, {"title": "朱元璋一方颁布大统历", "description": "乙未，朱元璋一方颁布大统历。", "start_year": 1367, "end_year": 1367, "time_original": "至正二十七年十一月", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "00942a12-25fd-58fd-a137-29f923b1049c"}, {"title": "徐达攻克益都，李老保投降，三名守臣死难", "description": "徐达攻下益都，李老保投降，巴延布哈、胡浚、张俊死难。随后又取寿光等县，命叶国珍留守。巴延布哈拒绝改仕，死难后，其妻阿嚕珍及两位弟弟的妻子各抱幼子投井而死。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "44a5c781-8140-5eb5-a3ae-6e14170bea2c"}, {"title": "律令编成，朱元璋复审后命刊布", "description": "律令编成后，朱元璋与诸臣重新审阅，多作删繁、减轻刑罚的处理，命人刊布。本书载令一百四十五条，后面的二百八十五条未标类别；《明史》记同一立法过程为令一百四十五条、律二百八十五条。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "24c845a9-7d1d-59b4-9b35-4ae5fd3e7b7c"}, {"title": "方国珍亲至军前投降，浙东平定", "description": "方国珍与弟弟国珉亲到汤和军前，库哩吉斯也来投降，一同被送往建康。邱楠获授韶州同知，詹鼎获官，其余人迁往濠州，浙东平定。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9d643baf-ec38-590d-b0a5-b7b8f1aea2df"}, {"title": "徐达接受章丘、济南投降，派陈胜守济南", "description": "王成献章丘投降，达多尔济等献济南投降，徐达命陈胜守济南。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f3eb2415-5453-5709-b395-c5c3b64fae82"}, {"title": "胡廷瑞接受邵武投降", "description": "胡廷瑞到邵武，李宗茂献城投降。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e23b7ef5-bb35-5d81-b076-8808d0f77871"}, {"title": "群臣再次劝进，朱元璋同意商议即位礼仪", "description": "李善长率百官坚持请求朱元璋称帝。朱元璋本想等天下平定再议，但在群臣屡请后，同意斟酌礼仪。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6a40207e-e837-5286-a0dc-97c39573ffee"}, {"title": "朱元璋在新宫祭告天地，请求征兆", "description": "朱元璋在新宫祭告天地，陈述群臣推戴之意，询问自己是否能成为百姓之主，请求用天气状况给予征兆。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6a222b77-af13-5ce4-87c5-c851826be29f"}, {"title": "汤和攻克福州", "description": "陈友定留赖正孙、谢英辅、邓益守福州，自己驻延平。汤和从海路进入五虎门，招降使者被库春杀死。军队登陆后击败库春，袁仁暗中归降，城门被打开。邓益抵抗战死，赖正孙、谢英辅等逃走；尹克仁投水，多尔玛不屈死于狱中。侯官的拜特穆尔杀死妻、妾及两个女儿，纵火焚烧后自刎。", "start_year": 1367, "end_year": 1367, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1367年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "15e422f2-deb5-5245-bede-d5543f71a9c3"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

